CREATE TABLE "rating_selection" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "season_year" smallint NOT NULL,
    "discipline_id" bigint NOT NULL,
    "age_group_id" bigint NOT NULL,
    "status" varchar(16) NOT NULL DEFAULT 'draft',
    "captain_user_id" bigint,
    "coach_user_id" bigint,
    "created_by_user_id" bigint NOT NULL,
    "locked_at" timestamptz,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "rating_selection_season_year_check" CHECK ("season_year" BETWEEN 2000 AND 2100),
    CONSTRAINT "rating_selection_status_check" CHECK ("status" IN ('draft', 'locked')),
    CONSTRAINT "rating_selection_lock_state_check"
        CHECK (("status" = 'draft' AND "locked_at" IS NULL) OR ("status" = 'locked' AND "locked_at" IS NOT NULL)),
    CONSTRAINT "rating_selection_discipline_id_fkey"
        FOREIGN KEY ("discipline_id") REFERENCES "discipline" ("id") ON DELETE RESTRICT,
    CONSTRAINT "rating_selection_age_group_id_fkey"
        FOREIGN KEY ("age_group_id") REFERENCES "age_group" ("id") ON DELETE RESTRICT,
    CONSTRAINT "rating_selection_captain_user_id_fkey"
        FOREIGN KEY ("captain_user_id") REFERENCES "user" ("id") ON DELETE RESTRICT,
    CONSTRAINT "rating_selection_coach_user_id_fkey"
        FOREIGN KEY ("coach_user_id") REFERENCES "user" ("id") ON DELETE RESTRICT,
    CONSTRAINT "rating_selection_created_by_user_id_fkey"
        FOREIGN KEY ("created_by_user_id") REFERENCES "user" ("id") ON DELETE RESTRICT,
    CONSTRAINT "rating_selection_scope_key"
        UNIQUE ("season_year", "discipline_id", "age_group_id")
);

CREATE TABLE "rating_selection_member" (
    "selection_id" bigint NOT NULL,
    "user_id" bigint NOT NULL,
    "selection_position" integer NOT NULL,
    PRIMARY KEY ("selection_id", "user_id"),
    CONSTRAINT "rating_selection_member_position_check" CHECK ("selection_position" > 0),
    CONSTRAINT "rating_selection_member_selection_id_fkey"
        FOREIGN KEY ("selection_id") REFERENCES "rating_selection" ("id") ON DELETE CASCADE,
    CONSTRAINT "rating_selection_member_user_id_fkey"
        FOREIGN KEY ("user_id") REFERENCES "user" ("id") ON DELETE RESTRICT,
    CONSTRAINT "rating_selection_member_position_key"
        UNIQUE ("selection_id", "selection_position")
);

CREATE INDEX "rating_selection_member_user_id_idx"
    ON "rating_selection_member" ("user_id");
